import { VoiceRecorder, ContextTray, ReviewApplyCard, type VoiceRecording } from '../../packages/highway-react/src/components/ui/agent-tools';
export function AgentToolsExample({attach,apply}:{attach:(audio:VoiceRecording)=>Promise<void>;apply:()=>Promise<void>}){
